// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Ensure array is non-empty as required by the function
        vm.assume(_tos.length > 0);
        // Ensure caddress is not the test contract itself and has no code (EOA or precompile) 
        // so the low-level call fails safely without changing state, making gas comparison 
        // the sole differentiator of loop execution.
        vm.assume(caddress != address(this));
        vm.assume(caddress.code.length == 0);

        // Bound the length to avoid out-of-gas during fuzzing
        uint256 len = _tos.length;
        len = bound(len, 1, 10);
        // Resize the array to the bounded length
        address[] memory tos = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            tos[i] = _tos[i];
        }

        uint256 gasBefore = gasleft();
        c.transfer(from, caddress, tos, v);
        uint256 gasUsed = gasBefore - gasleft();

        // The reference contract always uses more gas than the mutant would (since 
        // the mutant executes zero loop iterations). The mutant's base gas cost is 
        // the minimum possible (just require + return). We assert that the gas used 
        // is strictly greater than a zero-iteration baseline, which would fail on the mutant.
        // A zero-iteration transfer of a non-empty array consumes at most a small constant gas;
        // we compute that baseline by measuring a call that we know executes zero iterations 
        // (this is not possible directly, so we assert a lower bound that must hold for the 
        // reference but fails for the mutant).
        // Since the mutant does zero calls, its gas cost is minimal. The reference always does 
        // at least one call. Therefore, gasUsed must be > 21000 (base tx) + small overhead. 
        // We set a generous threshold that any call-bearing execution will exceed.
        assertTrue(gasUsed > 30000);
    }
}

