// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256 v, uint64 gasLimit) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(this));
        vm.assume(caddress != address(this));
        vm.assume(gasLimit >= 21000 && gasLimit <= 5_000_000);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(this));
            vm.assume(_tos[i] != address(0));
        }
        // We use a fresh instance each call to avoid state interference
        C target = new C();
        bool ok;
        try target.transfer{gas: gasLimit}(from, caddress, _tos, v) returns (bool) { ok = true; } catch { ok = false; }
        // Reference never reverts in a normal gas setting for any input, but mutant also never reverts.
        // This property is vacuously true for both, so we need a different observable.
        // Instead, observe that the reference attempts calls, which can cause a revert in a gas-starved context
        // when the destination is a contract that consumes all gas on call. The mutant does not call, so it survives.
        // We cannot force external reentrancy, so we rely on the fact that the reference calls at least once,
        // and with a carefully chosen gas limit, the call can fail and propagate revert, while mutant skips calls entirely.
        // Since we cannot mock the call destination, we exploit the fact that calling a non-contract address with a tiny gas stipend can cause revert in the reference but not in the mutant.
        // For a non-contract address, low-level call returns false, not revert, but the Solidity compiler may still revert if the subcall consumes all gas due to 63/64 rule? No, call returns false.
        // Therefore we need a contract that reverts. We can deploy a contract that reverts in fallback? Not allowed to deploy custom contracts.
        // Alternative: use c itself as the caddress, and _tos as an array containing the address of c. Then transferFrom selector on c will execute fallback? c has no fallback, so call returns false. No revert.
        // So revert difference is impossible to trigger without vm.mockCall.
        // Thus the only reliable observable is gas consumption. We capture gasleft() before and after.
        uint256 gasBefore = gasleft();
        // Reference does _tos.length calls, mutant does 0 calls. Gas difference is detectable.
        // But gas measurement fails if state changes affect gas? We use a fresh instance.
        target.transfer(from, caddress, _tos, v);
        uint256 gasAfter = gasleft();
        uint256 gasUsed = gasBefore - gasAfter;
        // Reference always uses more gas than the mutant for non-empty _tos.
        // We need the same input to test reference and mutant? Only one contract.
        // Ah! The test only has one C instance. It is either reference or mutant. We cannot compare both in one test.
        // The property must be a statement about c alone.
        // Since reference calls exactly _tos.length times, it always uses at least 2600 + 9000 (call cost) per element.
        // So we can assert: c.transfer(...) consumes at least ~11_000 * _tos.length gas.
        // But fuzzer provides contract compile choice? No, the test IS the contract under test.
        // We run against C once. "PASSES on reference, FAILS on mutant" means two separate runs with different C.
        // So our property must be: gasUsed >= _tos.length * 10000 (approx). Reference satisfies, mutant fails because its gasUsed is very small.
        // This avoids needing two contracts in one test.
    }
}
